import { useEffect, useState, useMemo, useRef } from 'react'

import { useClient } from 'cozy-client'
import { useDataProxy } from 'cozy-dataproxy-lib'

import logger from '@/lib/logger'
import { buildRecentQuery } from '@/queries'

const useDataProxyRecents = () => {
  const [data, setData] = useState([])
  const [fetchStatus, setFetchStatus] = useState('loading')
  const [error, setError] = useState(null)
  const [useFallback, setUseFallback] = useState(false)
  const [fallbackData, setFallbackData] = useState(null)
  const [fallbackStatus, setFallbackStatus] = useState('loading')
  const [fallbackError, setFallbackError] = useState(null)
  const dataProxy = useDataProxy()
  const client = useClient()

  const recentQuery = useMemo(() => buildRecentQuery(), [])

  useEffect(() => {
    const fetchRecents = async () => {
      setFetchStatus('loading')
      setError(null)
      try {
        const data = await dataProxy.recents()
        setData(data || [])
        setFetchStatus('loaded')
        setUseFallback(false)
      } catch (err) {
        logger.warn('Error fetching recents from dataproxy', err)
        setError(err)
        setUseFallback(true)
      }
    }

    if (dataProxy.dataProxyServicesAvailable) {
      fetchRecents()
    } else {
      setUseFallback(true)
    }
  }, [dataProxy])

  // Execute fallback query only once when useFallback becomes true
  useEffect(() => {
    if (!useFallback || !client || fallbackQueryExecutedRef.current) {
      return
    }

    fallbackQueryExecutedRef.current = true
    setFallbackStatus('loading')
    setFallbackError(null)

    const executeFallbackQuery = async () => {
      try {
        const result = await client.query(
          recentQuery.definition(),
          recentQuery.options
        )
        setFallbackData(result.data || [])
        setFallbackStatus('loaded')
      } catch (err) {
        logger.warn('Error fetching recents from fallback query', err)
        setFallbackError(err)
        setFallbackStatus('error')
      }
    }

    executeFallbackQuery()
  }, [useFallback, client, recentQuery])

  // Use fallback query result if dataProxy failed or is not available
  useEffect(() => {
    if (!useFallback) {
      return
    }

    if (fallbackStatus === 'loaded' && fallbackData) {
      setData(fallbackData)
      setFetchStatus('loaded')
      setError(null)
      return
    }

    if (fallbackStatus === 'error') {
      setFetchStatus('error')
      setError(fallbackError)
      return
    }

    if (fallbackStatus === 'loading') {
      setFetchStatus('loading')
    }
  }, [useFallback, fallbackStatus, fallbackData, fallbackError])

  return { data, fetchStatus, error }
}

export default useDataProxyRecents
